public class Solution {
    public boolean isPowerOfThree(int n) {
        // Check for base cases
        if (n <= 0) {
            return false;
        }

        // Check if n is a power of 3
        double logValue = Math.log10(n) / Math.log10(3);
        return (logValue - Math.floor(logValue)) == 0;
    }
}
```

